class Solution:
    def countSubstrings(self, s: str) -> int:
        counts = [None] + [[0] * m for m in range(1, 10)]
        ans = 0

        for ch in s:
            digit = ord(ch) - ord('0')
            new_counts = [None]

            for m in range(1, 10):
                cur = [0] * m

                for r, cnt in enumerate(counts[m]):
                    if cnt:
                        cur[(r * 10 + digit) % m] += cnt

                cur[digit % m] += 1
                new_counts.append(cur)

            counts = new_counts

            if digit != 0:
                ans += counts[digit][0]

        return ans
